-- Lane A figures for ap_chemistry: generated by build_load_sql.py, do not hand-edit.
-- 1 figures across 1 families, from scripts/lane-a-pilot/specs.json.
-- Entries are resolved by natural key, so this file is portable between environments.

begin;

-- 1. The renderer families this batch INTRODUCES (DECISION-0115: a row, not a CHECK).
-- Reused without introducing: mb_distribution

-- 2. The figures.
insert into app.figures (figure_id, subject_key, family, title, short_title, subtitle, caption, alt, x_label, y_label, note, synthetic, values_note, labels, params, y_tick_fmt, x_tick_fmt, status, source_note, published_at)
values ('chem-mb-entropy', 'ap_chemistry', 'mb_distribution', 'Kinetic energy spreads out as temperature rises', 'Energy dispersal with temperature', 'The same gas at two temperatures: the hotter distribution is broader', 'The same gas at two temperatures: the hotter distribution is broader', 'Two curves of the relative number of gas particles against kinetic energy for the same gas at a lower and a higher temperature. The higher-temperature curve has a lower peak and is broader and shifted to higher energy, so the kinetic energy is spread over a wider range of values. Illustrative data.', 'kinetic energy of a particle', 'relative number of particles', 'A broader distribution means the energy is more dispersed, so the entropy is greater.', true, null, '["Horizontal axis", "Vertical axis", "Kinetic-energy distribution at each temperature", "Broader distribution at the higher temperature"]'::jsonb, '{"x_max": 8.0, "series": [{"label": "Lower temperature", "theta": 0.78, "style": "solid"}, {"label": "Higher temperature", "theta": 1.48, "style": "dashed"}]}'::jsonb, '{:.2f}', null, 'published', 'cramapple-authored; batch=chem-next1-figures-2026-10-15', now())
on conflict (figure_id) do nothing;

-- 3. Where each figure is shown, resolved by natural key (protocol §6).
insert into app.figure_uses (figure_id, reference_entry_id, role)
select 'chem-mb-entropy', e.reference_entry_id, 'primary'
  from app.unit_reference_entries e
 where e.subject_key = 'ap_chemistry' and e.kind = 'convention'
   and e.title = 'Entropy increases with temperature (energy dispersal)' and e.status = 'published'
on conflict (figure_id, reference_entry_id) where reference_entry_id is not null do nothing;

-- 4. Guards: no dead figure, and every entry this batch covers got its figures.
do $$
declare v_dead text; v_n int;
begin
  select string_agg(f.figure_id, ', ') into v_dead
    from app.figures f left join app.figure_uses u on u.figure_id = f.figure_id
   where f.figure_id in ('chem-mb-entropy') and u.figure_id is null;
  if v_dead is not null then
    raise exception 'figures with no use, refusing to ship dead rows: %', v_dead;
  end if;
  select count(*) into v_n from app.figures where figure_id in ('chem-mb-entropy');
  if v_n <> 1 then
    raise exception 'expected 1 figures, found %', v_n;
  end if;
end $$;

commit;
